// Meta's webhook → which WhatsApp number it came to, plus the exact raw body for the
// X-Hub-Signature-256 check (Webhook node: Options → Raw Body ON).
// Next: "Respond: OK to Meta" answers 200 (the Webhook node's Respond = Using 'Respond to Webhook' Node).
const item = $input.first();
const hook = item.json;
const headers = hook.headers || {};
let raw = '';
try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) { raw = ''; }
let body = hook.body;
if (!body || typeof body !== 'object' || !Object.keys(body).length) {
  try { body = JSON.parse(raw); } catch (e) { body = {}; }
}
if (!raw) raw = JSON.stringify(body);

let pnid = '';
for (const e of body.entry || []) for (const ch of e.changes || []) {
  const id = ((ch.value || {}).metadata || {}).phone_number_id;
  if (id) { pnid = String(id); break; }
}
if (!pnid) return [{ json: { phone_number_id: '' } }];  // not a WhatsApp event we handle (still answered 200)
return [{ json: { phone_number_id: pnid, signature: String(headers['x-hub-signature-256'] || ''), raw, body } }];

// feeder.retexia.com → n8n (X-Retexia-Key checked by the webhook's Header Auth credential).
//   test_bot: one message through the real pipeline in test mode (nothing sent to WhatsApp)
//   check:    is this seller's number + token working? (Test connection)
//   send:     the seller's reply from the panel (free text, inside WhatsApp's 24 h window)
const b = $('Panel: Lingo Feeder').first().json.body || {};
const user = String(b.user_id || '');
if (!/^[0-9a-f-]{36}$/i.test(user)) throw new Error('user_id is required');
const action = String(b.action || '');
const cut = (s, n) => { s = String(s || '').trim(); return s.length > n ? s.slice(0, n) : s; };

if (action === 'test_bot') {
  const session = String(b.session || '').toLowerCase().replace(/[^a-z0-9-]/g, '').slice(0, 40) || 'panel';
  const tap = b.tap && b.tap.id ? { id: cut(b.tap.id, 60), title: cut(b.tap.title, 60) } : null;
  const text = cut(b.text, 1500);
  if (!text && !tap) throw new Error('text or tap is required');
  return [{ json: { action, user_id: user, message: {
    phone: 'test-' + session, waId: 'test.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8), name: cut(b.name, 40) || 'Test customer',
    text: tap ? `[tapped: ${tap.title}]` : text, media: null, tap, quotedId: cut(b.quoted_id, 120),
    referral: b.ad && (b.ad.headline || b.ad.body) ? { source_id: 'test-ad', source_url: '', source_type: 'ad', headline: cut(b.ad.headline, 200), body: cut(b.ad.body, 400) } : null,
    ts: Math.floor(Date.now() / 1000), start_product: Number(b.start_product) || null,
  } } }];
}
if (action === 'check') return [{ json: { action, user_id: user } }];
if (action === 'send') {
  const to = String(b.to || '').replace(/\D/g, '');
  const text = cut(b.text, 4000);
  if (!/^\d{6,20}$/.test(to) || !text) throw new Error('to and text are required');
  return [{ json: { action, user_id: user, to, text } }];
}
throw new Error('unknown action');

// The answer to feeder.retexia.com for "check" (Test connection), "send" (a reply from the panel) or an unknown seller.
const a = $('Panel Action').first().json;
const s = $('Seller').first().json;
const err = r => {
  const e = (r && (r.error || (r.body && r.body.error))) || null;
  if (!e) return '';
  return typeof e === 'string' ? e : `${e.code ? '(' + e.code + ') ' : ''}${e.error_user_msg || e.message || 'error'}`.slice(0, 300);
};
const body = r => (r && r.body !== undefined ? r.body : r) || {};

if (!s.ok) return [{ json: { reply: { ok: false, error: s.why || 'unknown seller' } } }];
if (!s.token || !s.phone_number_id) return [{ json: { reply: { ok: false, error: 'No WhatsApp number or token saved yet.' } } }];

if (a.action === 'check') {
  const info = $('WA: Number Info').first().json;
  const apps = $('WA: Subscribed Apps').isExecuted ? $('WA: Subscribed Apps').first().json : null;
  const e = err(info);
  const i = body(info);
  const subscribed = apps && !err(apps) ? (body(apps).data || []).length > 0 : null;
  return [{ json: { reply: {
    ok: !e && !!i.id, error: e || (i.id ? null : 'WhatsApp did not answer'),
    info: e ? null : { display_phone_number: i.display_phone_number || '', verified_name: i.verified_name || '', quality_rating: i.quality_rating || '',
                       code_verification_status: i.code_verification_status || '', name_status: i.name_status || '', platform_type: i.platform_type || '' },
    subscribed, subscribe_error: apps ? err(apps) || null : null,
  } } }];
}

// send
const r = $('WA: Send Reply').first().json;
const e = err(r);
const id = ((body(r).messages || [])[0] || {}).id || null;
return [{ json: { reply: { ok: !e && !!id, wa_id: id, error: e || (id ? null : 'WhatsApp did not accept the message') } } }];

// Lingo Feeder: checks Meta's signature, then splits the webhook: delivery statuses, the seller's own replies from
// the WhatsApp Business app (echoes) and the customer's message(s). The HMAC-SHA256 of the raw body
// with this number's app secret (Retexia's in embedded mode) is made by the "Sign Body" Crypto node,
// so no NODE_FUNCTION_ALLOW_BUILTIN setting is needed on the n8n server.
const w = $('Read Webhook').first().json;
const num = $('Number').first().json;
const cut = (s, n) => { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };
const keep = (s, n) => { s = String(s || '').replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };

const sign = $('Sign Body').isExecuted ? ($('Sign Body').first().json || {}) : {};
const expect = sign.hmac ? 'sha256=' + String(sign.hmac).toLowerCase() : '';
const got = String(w.signature || '').toLowerCase();
let diff = expect.length === got.length && expect.length > 7 ? 0 : 1;
for (let i = 0; i < Math.min(expect.length, got.length); i++) diff |= expect.charCodeAt(i) ^ got.charCodeAt(i);
if (diff !== 0) return [];                            // not from Meta (or the app secret is wrong): ignore

const statuses = [], echoes = [];
let msgs = [], contacts = [];
for (const e of w.body.entry || []) for (const ch of e.changes || []) {
  const v = ch.value || {};
  if (String((v.metadata || {}).phone_number_id || '') !== String(num.phone_number_id)) continue;
  if (ch.field === 'messages') {
    for (const s of v.statuses || []) {
      const err = (s.errors || [])[0] || {};
      statuses.push({
        id: s.id, status: s.status, recipient: s.recipient_id,
        billable: s.pricing ? !!s.pricing.billable : null, category: s.pricing ? (s.pricing.category || '') : '',
        error: s.status === 'failed' ? cut(`${err.code || ''} ${err.title || ''} ${(err.error_data || {}).details || err.message || ''}`, 300) : null,
      });
    }
    contacts = contacts.concat(v.contacts || []);
    msgs = msgs.concat(v.messages || []);
  } else if (ch.field === 'smb_message_echoes') {
    for (const x of v.message_echoes || []) {
      const text = x.type === 'text' ? (x.text || {}).body : `[${x.type || 'message'}] ${((x[x.type] || {}).caption) || ''}`;
      echoes.push({ to: String(x.to || ''), id: x.id, text: cut(text, 4000) });
    }
  }
}

let message = null;
if (msgs.length) {
  const from = msgs[0].from;
  const mine = msgs.filter(x => x.from === from);
  const texts = [];
  let media = null, tap = null, quotedId = '', referral = null;
  for (const x of mine) {
    if (x.context && x.context.id && !quotedId) quotedId = x.context.id;
    if (x.referral && !referral) referral = x.referral;
    switch (x.type) {
      case 'text': texts.push(x.text.body); break;
      case 'image': if (!media) media = { kind: 'image', id: x.image.id, mime: x.image.mime_type }; if (x.image.caption) texts.push(x.image.caption); break;
      case 'audio': if (!media) media = { kind: 'audio', id: x.audio.id, mime: x.audio.mime_type }; break;
      case 'video': texts.push('[video] ' + ((x.video || {}).caption || '')); break;
      case 'document': texts.push(`[document ${(x.document || {}).filename || ''}] ${(x.document || {}).caption || ''}`); break;
      case 'location': { const l = x.location || {}; texts.push(`[location ${l.latitude},${l.longitude} ${l.name || ''} ${l.address || ''}]`); break; }
      case 'contacts': { const c = (x.contacts || [])[0] || {}; texts.push(`[contact ${(c.name || {}).formatted_name || ''} ${((c.phones || [])[0] || {}).phone || ''}]`); break; }
      case 'interactive': {
        const it = x.interactive || {};
        const r = it.button_reply || it.list_reply;
        if (r) { tap = tap || { id: r.id, title: r.title }; texts.push(`[tapped: ${r.title}]`); }
        break;
      }
      case 'button': tap = tap || { id: x.button.payload, title: x.button.text }; texts.push(`[tapped: ${x.button.text}]`); break;
      default: break;                                  // reaction, sticker, unsupported, system…
    }
  }
  const text = keep(texts.join('\n'), 1500);                // line breaks matter (addresses, our details form)
  if (text || media) {
    const last = mine[mine.length - 1];
    const contact = contacts.find(c => c.wa_id === from) || contacts[0] || {};
    message = {
      phone: String(from), waId: last.id, name: cut((contact.profile || {}).name, 80),
      text, media, tap, quotedId,
      referral: referral ? {
        source_id: referral.source_id || '', source_url: referral.source_url || '', source_type: referral.source_type || '',
        headline: cut(referral.headline, 200), body: cut(referral.body, 400),
      } : null,
      ts: Number(last.timestamp) || Math.floor(Date.now() / 1000),
    };
  }
}
return [{ json: { statuses, echoes, message } }];

// One customer turn, from WhatsApp or from the panel's "Try Lingo" (test mode: nothing is sent to
// WhatsApp, rows are marked test). Every later node reads $('Message').
const base = $('Verify & Split').isExecuted
  ? (() => {
      const v = $('Verify & Split').first().json;
      const n = $('Number').first().json;
      return { ...v.message, user_id: n.user_id, phone_number_id: n.phone_number_id, token: n.token, seller: n.seller || {}, test: false, start_product: null };
    })()
  : (() => {
      const a = $('Panel Action').first().json;
      const s = $('Seller').first().json;
      return { ...a.message, user_id: s.user_id, phone_number_id: s.phone_number_id, token: null, seller: s.seller || {}, test: true };
    })();
const kind = base.tap ? 'tap' : base.media ? (base.media.kind === 'audio' ? 'voice' : 'image') : 'text';
return [{ json: { ...base, kind } }];

// First customer from a NEW ad whose words didn't name a product clearly: one small AI call decides
// which product the ad sells. Saved in lingo_feeder.ads, so later customers from that ad cost nothing.
// The only call that sees the whole product list, once per ad.
const ai = (($('Message').first().json.seller || {}).ai) || {};
const g = $input.first().json;
const ad = g.ad || {};
const list = (g.products || []).map(p => `${p.id}: ${p.n}${p.k ? ' (' + String(p.k).slice(0, 60) + ')' : ''}`).join('\n');
const model = ai.ad_match || ai.cheap || 'gpt-5.4-nano';
const req = {
  model,
  messages: [
    { role: 'system', content: 'Which product does this Facebook/Instagram ad sell? Answer with the product id from the list, or 0 if none fits.' },
    { role: 'user', content: `Ad headline: ${ad.headline || '-'}\nAd text: ${ad.body || '-'}\n\nProducts:\n${list}` },
  ],
  response_format: { type: 'json_schema', json_schema: { name: 'ad_product', strict: true, schema: {
    type: 'object', additionalProperties: false, properties: { p: { type: 'integer' } }, required: ['p'] } } },
  max_completion_tokens: 200,
};
if (/^gpt-5/.test(model) && ai.openai_reasoning) req.reasoning_effort = String(ai.openai_reasoning);
return [{ json: { task: 'ad_match', provider: 'openai', model, req, started: Date.now() } }];

// The ad-match answer → bot_set_ad (0 = nothing fits: the seller picks the product in Products → Ads).
const m = $('Message').first().json;
const gate = $('Gate').first().json;
const r = $input.first().json || {};
let pid = 0;
try { pid = Number(JSON.parse(String((((r.choices || [])[0] || {}).message || {}).content || '{}')).p) || 0; } catch (e) { pid = 0; }
return [{ json: { p: { user_id: m.user_id, ad_id: (gate.ad || {}).id, product_id: pid || null, phone: m.phone } } }];

// Voice note / photo → text with Gemini, once (later steps only see the text, never the media again).
// Voice notes: Gemini 3.5 Flash (settings.ai.media_audio) hears Sinhala far better than Flash-Lite; it gets the
// product the customer is talking about as a hint, writes English words in English letters ("diabetes",
// "order") and never invents. Photos: Flash-Lite (settings.ai.media).
const m = $('Message').first().json;
const ai = (m.seller || {}).ai || {};
const gate = $('Gate').isExecuted ? ($('Gate').first().json || {}) : {};
let b64 = '';
try { b64 = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64'); } catch (e) { b64 = ''; }
const audio = m.media.kind === 'audio';
const mime = String(m.media.mime || (audio ? 'audio/ogg' : 'image/jpeg')).split(';')[0].trim();
const hint = gate.product_name ? `\nThe chat is about this product: ${gate.product_name}.` : '';
const prompt = audio
  ? `Transcribe this WhatsApp voice note from a Sri Lankan customer to an online shop that sells Ayurvedic and home products, word for word.
- Sinhala speech → Sinhala script, as it was said (spoken Sinhala, not formal).
- English words the speaker uses (diabetes, sugar, cholesterol, pressure, gastric, order, delivery, address, cash on delivery, product names) → write them in English letters. Never spell an English word with Sinhala letters, and never mix Sinhala and English letters in one word.
- If they speak Singlish or English, write it in English letters.
- Phone numbers as digits. Keep names, places and addresses exactly.
- Don't translate, summarise, answer or add anything. If a part can't be heard, write (unclear).${hint}
Output only the transcript.`
  : `A customer sent this photo to a Sri Lankan online shop. In max 25 English words say what it shows. If a product, brand or product name is visible, write the name exactly as printed. If it shows an address, phone number, payment slip, order details or a problem (damaged parcel, skin, hair…), copy or describe it.${hint}
Output only that.`;
const model = audio ? (ai.media_audio || 'gemini-3.5-flash') : (ai.media || 'gemini-3.5-flash-lite');
const req = b64 ? {
  systemInstruction: { parts: [{ text: prompt }] },
  contents: [{ role: 'user', parts: [{ inlineData: { mimeType: mime, data: b64 } }] }],
  generationConfig: { temperature: 0, maxOutputTokens: 600, thinkingConfig: { thinkingLevel: ai.gemini_thinking || 'minimal' } },
} : { contents: [] };
return [{ json: { ok: !!b64, task: 'media', provider: 'gemini', model, req, started: Date.now() } }];

// Voice note words / photo description (+ caption) → one line of text for the turn.
const m = $('Message').first().json;
const g = $input.first().json || {};
const said = ((((g.candidates || [])[0] || {}).content || {}).parts || [])
  .filter(x => !x.thought).map(x => x.text || '').join(' ').replace(/\s+/g, ' ').trim().split(" ").slice(0, 150).join(" ");
const text = m.media.kind === 'audio'
  ? (said ? `[voice] ${said}` : '[voice note - could not understand]') + (m.text ? ' ' + m.text : '')
  : (said ? `[photo: ${said}]` : '[photo]') + (m.text ? ' ' + m.text : '');
return [{ json: { text } }];

// One row for the batching buffer (text, or the voice note / photo as text), with the AI usage of
// this message's ad match and media call, so every call is logged even if the batch moves on.
const m = $('Message').first().json;
const usage = [];
const add = (node, builder) => {
  if (!$(node).isExecuted) return;
  const r = $(node).first().json || {};
  const b = $(builder).first().json || {};
  const u = r.usage || r.usageMetadata || null;
  usage.push({ task: b.task, provider: b.provider, model: b.model, usage: u, ok: !r.error && !!u, ms: b.started ? Date.now() - b.started : null,
               error: r.error ? String(r.error.message || r.error).slice(0, 300) : null });
};
add('AI: Ad Match', 'Build Ad Match');
add('Gemini: Media', 'Build Media Request');
const text = $('Media to Text').isExecuted ? $('Media to Text').first().json.text : m.text;
return [{ json: { p: {
  user_id: m.user_id, phone: m.phone, wa_id: m.waId, content: text || '[media]', kind: m.kind, quoted_id: m.quotedId || null,
  tap: m.tap ? m.tap.id : null, wa_ts: m.ts, test: !!m.test, usage,
} } }];

// What does the customer want? Most messages are understood here in code, with no AI:
//   • button / list taps, the ad's pre-filled "Hello! Can I get more info on this?"
//   • Meta lead-form messages and our details form filled in (name / address / phone)
//   • a reply to what Lingo asked (a quantity, "ow" to the summary, the new address…)
//   • short common questions, typos and all (kiyada? delivery? dawas kiyak yanawada?)
//   • spam links
// Anything else → ONE AI call ("brain") that both reads the message and writes Lingo's reply, with
// only this chat's product (never the catalogue). OpenAI first; Gemini if OpenAI fails.
// ---- Lingo Feeder shared helpers (copied into each Code node that says "@include lib.js") ----
const cut = (s, n) => { s = String(s == null ? '' : s); return Array.from(s).length > n ? Array.from(s).slice(0, n).join('') + '…' : s; };
const clip = (s, n) => Array.from(String(s == null ? '' : s)).slice(0, n).join('');
const has = v => v !== undefined && v !== null && String(v).trim() !== '';
const money = n => Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });

/** Lower case, no emojis / punctuation, single spaces: what the quick rules match against. */
const normalize = s => String(s || '').normalize('NFC').toLowerCase()
  .replace(/\p{Extended_Pictographic}/gu, ' ').replace(/[\u{1F3FB}-\u{1F3FF}\u{FE0F}\u{20E3}‍]/gu, '')
  .replace(/[\p{P}\p{S}]/gu, ' ').replace(/\s+/g, ' ').trim();

/** A Sri Lankan mobile number → 0XXXXXXXXX (else ''). */
const localPhone = v => {
  const d = String(v || '').replace(/\D/g, '');
  if (/^94\d{9}$/.test(d)) return '0' + d.slice(2);
  if (/^0\d{9}$/.test(d)) return d;
  if (/^[1-9]\d{8}$/.test(d)) return '0' + d;
  return '';
};

/** A WhatsApp profile name that looks like a first name ("Nimal", "නිමල්"), else ''. */
const NOT_NAMES = new Set(['shop', 'store', 'stores', 'official', 'online', 'mobile', 'phone', 'user', 'whatsapp', 'business', 'enterprises', 'lk', 'the', 'mr', 'mrs', 'miss', 'dr', 'hi', 'hello']);
const firstName = n => {
  const w = String(n || '').replace(/[^A-Za-z඀-෿ ]+/g, ' ').trim().split(/\s+/)[0] || '';
  if (/^[A-Za-z]{2,20}$/.test(w) && !NOT_NAMES.has(w.toLowerCase())) return w[0].toUpperCase() + w.slice(1).toLowerCase();
  if (/^[඀-෿]{2,20}$/.test(w)) return w;
  return '';
};

/** Which style the customer writes in: si (Sinhala script) · sg (Singlish) · en, else keep prev. */
const SINGLISH = /\b(kiyada|kiyd|kiyda|keyada|puluwan\w*|pluwan\w*|ona|oni|one|onee|mata|matath|eka|ekak|akak|dekak|dr|ganna|gnna|danna|denna|karanna|thiyenawa\w*|thiyanawa\w*|nadda|neda|nedda|nathi|na|naa|ow|owu|hari|mokak\w*|kohom\w*|koheda|kawad\w*|wenawa\w*|gena|ewanna|awanna|evanna|bonna|beheth|gedara\w*|salli|ganan|gana|mila|dawas|kiyak|yanawa\w*|enawa\w*|ammala|lamai\w*|ayata|walata|nam|thama|tama|aiyo|ayyo|aney|ane|ela|harida|denne|ganne|wage|witharada|witharai|puluwanda|onada)\b/;
const ENGLISH = /\b(how|what|when|where|which|is|are|can|could|do|does|please|want|need|send|my|the|your|price|much|deliver|order|thank|thanks|hello|available)\b/;
const guessLang = (text, prev) => {
  const s = String(text || '');
  const si = (s.match(/[඀-෿]/g) || []).length;
  const lat = (s.match(/[A-Za-z]/g) || []).length;
  if (si >= 2 && si >= lat * 0.5) return 'si';
  if (lat < 3) return prev;
  const w = s.toLowerCase();
  if (SINGLISH.test(w)) return 'sg';
  if (ENGLISH.test(w) && w.split(/\s+/).length >= 2) return 'en';
  return prev;
};

/** Good morning / afternoon / evening / night key, Sri Lanka time. */
const greetKey = (d = new Date()) => {
  const h = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Colombo', hour: 'numeric', hour12: false }).format(d)) % 24;
  return h >= 4 && h < 12 ? 'greet_morning' : h >= 12 && h < 16 ? 'greet_afternoon' : h >= 16 && h < 20 ? 'greet_evening' : 'greet_night';
};

/** One text in the customer's style (Singlish → Sinhala text if no Singlish one), placeholders filled.
 *  With variants (settings.variants) a different wording is picked from turn to turn (seed). */
const hashOf = s => { let h = 2166136261; for (const ch of String(s)) { h ^= ch.codePointAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const makeText = (texts, lang, variants = {}, seed = '') => (key, vals = {}) => {
  const t = texts[key] || {};
  const main = String(t[lang] || (lang === 'sg' ? t.si : '') || t.si || t.en || '');
  const v = (variants || {})[key] || {};
  const more = Array.isArray(v[lang]) ? v[lang] : [];
  const pool = [main, ...more.filter(x => x && x !== main)].filter(Boolean);
  const raw = pool.length > 1 && seed ? pool[hashOf(seed + '|' + key) % pool.length] : main;
  return raw.replace(/\{(\w+)\}/g, (x, k) => (k in vals ? String(vals[k] == null ? '' : vals[k]) : x))
    .replace(/[ \t]{2,}/g, ' ').replace(/ +([!?.,😊🙏👇])/g, ' $1').replace(/^ +| +$/gm, '').replace(/ ([!?.,])/g, '$1')
    .replace(/\n{3,}/g, '\n\n').trim();
};

/** A long chat reply → 2-3 short WhatsApp messages, split at sentence ends (like people text). */
const splitReply = r => {
  const t = String(r || '').trim();
  if (Array.from(t).length < 110) return [t];
  const parts = t.split(/(?<=[.!?。])\s+|\n+/).map(x => x.trim()).filter(Boolean);
  const out = [];
  for (const x of parts) {
    if (out.length && (Array.from(out[out.length - 1]).length < 35 || out.length >= 3 || /^\p{Extended_Pictographic}+$/u.test(x))) out[out.length - 1] += ' ' + x;
    else out.push(x);
  }
  return out.length ? out : [t];
};

/** The Click-to-WhatsApp pre-filled text ("Hello! Can I get more info on this?") and other openers. */
