}
function okReply() {
  if (/\[offered to order/.test(lastNote)) { log.push('[ok: already offered to order]'); return; }   // never the same offer twice in a row
  step({ kind: 'buttons', text: T('ok_reply', V()), buttons: [B('ORDER', 'btn_order'), B('USAGE', 'btn_usage')] });
